    if ($i % 2 == 1) {
        // Odd step: swap left (0) and middle (1)
        if ($pos == 0) $pos = 1;
        else if ($pos == 1) $pos = 0;
    } else {
        // Even step: swap middle (1) and right (2)
        if ($pos == 1) $pos = 2;
        else if ($pos == 2) $pos = 1;
    }
}
echo $pos;
?>
